(7663545, 1249633, 86447, '<td valign="top">Lovely girl.   Beautiful colors.   wonderful composition.<br/> <br/>I wish her eyes were more in focus instead of her lips, though.</td>', 'Lovely girl.   Beautiful colors.   wonderful composition. I wish her eyes were more in focus instead of her lips, though.', '2020-05-22 11:17:12.000000', NULL, 1),
(7663546, 1249414, 86447, '<td valign="top">I love this!<br/> <br/>Personally, I would not call a photo of hands a "portrait".<br/> <br/>I do love hands and have photos of a bunch of them.   They say so much about a person, I think.</td>', 'I love this! Personally, I would not call a photo of hands a "portrait". I do love hands and have photos of a bunch of them.   They say so much about a person, I think.', '2020-05-22 11:18:13.000000', NULL, 1),
(7663547, 1249353, 86447, '<td valign="top">Ya couldn''t have smiled?   Even for yourself?  Ha!</td>', 'Ya couldn''t have smiled?   Even for yourself?  Ha!', '2020-05-22 11:19:01.000000', NULL, 1),
(7663548, 1249843, 86447, '<td valign="top">I love it, Girish!<br/>Might have been more appealing without the cloth.</td>', 'I love it, Girish!Might have been more appealing without the cloth.', '2020-05-22 11:19:44.000000', NULL, 1),
